def group_anagrams(words: List[str]) -> List[List[str]]:
    """Group words that are anagrams; sort each group, then sort the groups."""
    # Group words by their sorted characters
    sorted_groups = {}
    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word in sorted_groups:
            sorted_groups[sorted_word].append(word)
        else:
            sorted_groups[sorted_word] = [word]

